TP.register({id:"lp9-g3",lp:9,grade:"3",mode:"baseline",nextGrade:"4th grade",build(E){const F=E.F;const FLU_TITLE="Morning on the Dock";const FLU=["Rosalind was always the first one awake at camp. She pulled on her boots, picked up the water jug, and walked down the hill to the dock before anyone else was moving.","The lake was flat and gray at that hour. Mist sat on top of the water in long low strips. If she stood still she could hear the dock boards creak, a fish turn over somewhere out in the reeds, and nothing else at all.","Her job was the canoes. Six of them were tied along the left side of the dock. Each one had to be checked and scooped out if rain had collected inside. Rosalind used an old plastic cup and counted out loud while she worked.","Six canoes meant six trips down the dock and back. Rosalind worked from the far end toward the shore. So the last boat she finished was the one closest to the ramp. That was the one the morning class always took first. Three of the canoes were dry. Two had an inch of rainwater in the bottom. The sixth had a frog in it. She carried the frog to the reeds in the cup before she scooped anything out. She liked the job because nobody checked it and she could tell when it was done well.","By the time the cook rang the bell, the mist had lifted off the middle of the lake. The far shore of pines had come back into view. Rosalind carried the full jug up the hill and got to the table first."].join("\n\n");const STORY_TITLE="The Canoe Partner";const STORY=["Theo had been in a canoe exactly once before, and that once had been in the shallow end of a swimming pool.","On the second day of camp the counselor read out the canoe pairs. Theo was put with a girl named Delphine, who had been coming to the lake every summer since she was five.","“I am going to be terrible at this,” Theo said.","“Everybody is terrible at this,” said Delphine. “Sit in front. Watch my paddle and copy it.”","The lake was a sheet of glass that morning. Theo copied the way Delphine dipped her paddle, pulled, and lifted it out. For a while the canoe wandered left, then right, then left again. Delphine did not say one word about it.","Then, somewhere past the big rock, the wandering stopped. The canoe went straight. Theo's arms were noodles by then, but he kept pulling all the way to the far dock and back.","At dinner Delphine told the whole table that Theo had steered the last ten minutes by himself. Theo did not answer, but he sat up a little straighter."].join("\n\n");const T1={title:"Where the Lake Water Comes From",body:"Pine Lake is not fed by a pipe. It is fed by rain and snow that lands on the hills all around it. Every drop that falls on those hills runs downhill, and the low place it runs to is the lake. All that land together is called the lake's watershed.\n\nA watershed can be much bigger than the lake itself. Pine Lake covers about half a square mile. Its watershed covers about nine square miles. So for every bit of water that falls straight onto the lake, much more arrives by running down the hills."};const T2={title:"Why Camp Washes Dishes Uphill",body:"Whatever sits on the ground in a watershed can end up in the lake. Soap, fish bait, and bits of food all travel downhill with the rain.\n\nCamp has three rules about this. Wash dishes at least thirty steps back from the shore. So the soapy water soaks into the ground instead of running in. Keep food scraps in a covered bin. Leave the plants along the shore standing. That is because their roots hold the soil in place when it rains."};const PLAN_READ=["How Camp Plans a Paddle Day.","Camp does not decide in the morning whether to paddle. The plan is made the night before, and three things go into it.","First the counselors read the weather. A calm lake is an easy lake, so a windy forecast moves the paddle to the afternoon or to another day.","Second they count the life jackets and match a size to every paddler. Nobody goes out without one that fits.","Third they pick the route. A short route hugs the near shore. A long route crosses to the pine point and comes back along the reeds.","By bedtime the plan is on the board by the dining hall, so the first question at breakfast is already answered."].join("\n\n");const WORDS=["campfire","shoreline","downhill","refill","unpack","mislabel","darkness","restful","treeless","direction","canoe","through"];const WRITE_DIR="Write on your paper. When you finish, hold it up or read it to your teacher.";const pills=(...w)=>`<div class="row center" style="margin-top:18px;gap:18px;flex-wrap:wrap">${w.map(x=>`<span class="pill" style="font-size:1.4rem">${x}</span>`).join("")}</div>`;const checklist=items=>`<ul class="qlist" style="margin-top:14px">${items.map(x=>`<li>${x}</li>`).join("")}</ul>`;const lookBack=(label,inner)=>`<details class="look-back" open><summary>Look back at ${label}</summary>${inner}</details>`;const group=(inner,label)=>`<div style="text-align:center">${inner}<p class="fig-label" style="margin:4px 0 0">${label}</p></div>`;const stackFig=inner=>`<div style="display:flex;flex-direction:column;gap:12px;align-items:center;margin-top:10px">${inner}</div>`;const twoTexts=()=>`<div class="texts">${[T1,T2].map((t,i)=>`<article><h3>Text ${i+1}: ${t.title}</h3>${t.body.split(/\n\s*\n/).map(p=>`<p>${p}</p>`).join("")}</article>`).join("")}</div>`;function noteBoxes(a,b){const bx=t=>`<div style="border:3px dashed var(--line);border-radius:16px;min-width:250px;min-height:100px;padding:8px 16px;background:var(--surface)"><p class="fig-label" style="margin:0;font-size:1.35rem">${t}</p></div>`;return`<div class="figure">${bx(a)}${bx(b)}</div>`}function splitBar(xs,shade){const W=330,H=120;let s=`<svg viewBox="0 0 ${W+8} ${H+8}" width="${W+8}" role="img" aria-label="A strip cut into ${xs.length-1} parts with ${shade} of them shaded">`;for(let k=0;k<xs.length-1;k++)s+=`<rect x="${4+xs[k]*W}" y="4" width="${(xs[k+1]-xs[k])*W}" height="${H}" fill="${k<shade?"var(--gold)":"var(--surface)"}" stroke="var(--fig-ink)" stroke-width="3.5"/>`;return s+"</svg>"}function splitRect(rows,a,b){const u=36,ox=96,oy=12,cols=a+b,W=ox+cols*u+20,H=oy+rows*u+46;let s=`<svg viewBox="0 0 ${W} ${H}" width="${W}" style="max-width:100%;height:auto" role="img" aria-label="A rectangle of square tiles, ${rows} rows tall and ${cols} columns long, with a heavy line splitting it into a block ${a} columns wide and a block ${b} columns wide">`;for(let r=0;r<rows;r++)for(let c=0;c<cols;c++)s+=`<rect x="${ox+c*u}" y="${oy+r*u}" width="${u}" height="${u}" fill="${c<a?"var(--sea-soft)":"var(--gold)"}" fill-opacity="${c<a?"1":".5"}" stroke="var(--fig-ink)" stroke-width="2"/>`;s+=`<line x1="${ox+a*u}" y1="${oy}" x2="${ox+a*u}" y2="${oy+rows*u}" stroke="var(--fig-ink)" stroke-width="6"/>`;const t=(x,y,txt,an)=>`<text x="${x}" y="${y}" text-anchor="${an||"middle"}" font-size="20" font-weight="700" fill="var(--ink)">${txt}</text>`;s+=t(ox+a*u/2,oy+rows*u+30,a+" tiles")+t(ox+a*u+b*u/2,oy+rows*u+30,b+" tiles")+t(ox-14,oy+rows*u/2+7,rows+" tiles","end");return s+"</svg>"}function ellSite(){const u=38,ox=60,oy=34,W=ox+7*u+76,H=oy+5*u+46;let s=`<svg viewBox="0 0 ${W} ${H}" width="${W}" style="max-width:100%;height:auto" role="img" aria-label="An L shaped campsite on a grid of square meters. The bottom block is 7 squares long and 2 squares tall. A block 3 squares long and 3 squares tall sits on top of its left end.">`;for(let r=0;r<5;r++)for(let c=0;c<7;c++){if(!(r>=3||c<3))continue;s+=`<rect x="${ox+c*u}" y="${oy+r*u}" width="${u}" height="${u}" fill="var(--sea-soft)" stroke="var(--fig-ink)" stroke-width="2"/>`}const t=(x,y,txt,an)=>`<text x="${x}" y="${y}" text-anchor="${an||"middle"}" font-size="20" font-weight="700" fill="var(--ink)">${txt}</text>`;s+=t(ox+1.5*u,oy-11,"3 m")+t(ox+3.5*u,oy+5*u+32,"7 m")+t(ox-13,oy+1.5*u+7,"3 m","end")+t(ox+7*u+13,oy+4*u+7,"2 m","start");return s+"</svg>"}const STOPS=[{id:1,title:"Camp Label Words",short:"Label Words",parts:[{std:["RF.3.3"],kind:"words",words:WORDS,n:12,dur:80,dir:"Read each word out loud. Look for a part you already know at the start or the end of the word.",desc:"reading longer words with prefixes, suffixes, more than one syllable, and irregular spellings",key:["Read each word in order: campfire, shoreline, downhill, refill, unpack, mislabel, darkness, restful, treeless, direction, canoe, through.","Watch for: compound words broken into two parts (campfire, shoreline, downhill), the prefixes re-, un-, and mis- (refill, unpack, mislabel), the suffixes -ness, -ful, and -less (darkness, restful, treeless), the -tion ending (direction), and two irregular spellings where the letters do not say what they usually say (canoe, through).","Optional word-part check: ask what re- does in refill, meaning fill it again, and what -less does in treeless, meaning without trees."]}]},{id:2,title:"Read the Dock Story",short:"Read Aloud",parts:[{std:["RF.3.4"],kind:"read",n:0,label:"words read correctly",dur:175,dir:"Read the story out loud. Use your best reading voice.",desc:"a grade-level story read aloud",html:()=>F.passage(FLU,FLU_TITLE),key:["__WC__ words, not counting the title. Time 1 minute and mark errors and self-corrections on your own copy. Let the student finish the passage.","Spring grade 3 benchmark: about 112 words correct per minute, from the Hasbrouck and Tindal 2017 spring 50th percentile. 90th percentile on that same table is about 166. For the 25th and 10th percentile rows, read them off your own copy of that table rather than from here. The passage is long enough that a reader at the 90th percentile still has text left when the minute ends, so the score is not capped by the page.","Note pace, phrasing, and expression. Listen for the three-part list in the sentence about what she could hear, and for a steadier voice in the last paragraph."]}]},{id:3,title:"Story Questions",short:"Story Qs",parts:[{title:"Prove It",std:["RL.3.1"],dur:110,dir:"Read the story. Then answer out loud. Look back at the story to prove each answer.",desc:"asking and answering story questions using the exact words in the text",html:()=>F.passage(STORY,STORY_TITLE,true),qs:["How many times had Theo been in a canoe before camp. Where? Read the words from the story.","Who was Theo's canoe partner. How long had she been coming to the lake? Read the sentence that tells you.","What two things did Delphine tell Theo to do? Find the words in the story.","Where did the canoe stop wandering? Read the words that tell you.","Your turn to be the teacher. Ask one question that this story answers. Start with Who, What, or Why."],key:["Once, in the shallow end of a swimming pool. Reads “Theo had been in a canoe exactly once before, and that once had been in the shallow end of a swimming pool.” (RL.3.1)","Delphine, since she was five. Reads “a girl named Delphine, who had been coming to the lake every summer since she was five.” (RL.3.1)","Sit in front, and watch her paddle and copy it. Reads “Sit in front. Watch my paddle and copy it.” (RL.3.1)","Past the big rock. Reads “somewhere past the big rock, the wandering stopped.” (RL.3.1)","Asks a question the story can answer, such as: Who read out the canoe pairs? What did Delphine say at dinner? Why did Theo think he would be terrible? (RL.3.1, asks questions)"]},{title:"Word Meanings",std:["RL.3.4"],dur:95,dir:"Answer out loud. Use the story to explain each answer.",desc:"word and phrase meanings in a story, telling literal from nonliteral language",html:()=>lookBack("the story",F.passage(STORY,STORY_TITLE,true)),qs:["The story says the lake was a sheet of glass. Was it really glass? What does that tell you about the lake?","Theo's arms were noodles. Were they really noodles? What does this tell you?","What does wandered mean in “the canoe wandered left, then right, then left again”?","Delphine says, “Everybody is terrible at this.” Does she mean every single person on earth? What is she really saying?","One of these means exactly what the words say and one does not. Which is which? A: “He kept pulling all the way to the far dock and back.” B: “The lake was a sheet of glass.”"],key:["Nonliteral. The water was so flat, smooth, and still that it looked like a pane of glass, with no waves at all. (RL.3.4, nonliteral language)","Nonliteral. His arms were so tired from paddling that they felt soft and floppy and hard to control. (RL.3.4, nonliteral language)","Drifted off course from side to side instead of going straight. The next sentence, about the canoe going straight, shows the contrast. (RL.3.4, meaning of a word as used in the text)","No. She is stretching it to make Theo feel better. She means that nearly everyone is bad at paddling when they start, so he is not the only one. (RL.3.4, nonliteral language)","A is literal, because he really did paddle to the far dock and back. B is nonliteral, because the lake was water, not glass. It means the water was perfectly smooth. (RL.3.4, literal and nonliteral)"]}]},{id:4,title:"Two Lake Texts",short:"Two Texts",parts:[{title:"Use the Text",std:["RI.3.1"],dur:105,dir:"Read both texts to yourself. Then answer out loud. Look back at the text to prove each answer.",desc:"questions about an informational text answered with the exact words in the text",html:()=>twoTexts(),qs:["What feeds Pine Lake? Read the words from Text 1.","What is a watershed? Read the sentence that tells you.","How big is Pine Lake, and how big is its watershed? Find the numbers in Text 1.","Where does a drop of rain that falls on the hills end up? Read the words that tell you.","Your turn to be the teacher. Ask one question that Text 2 answers. Start with How, What, or Why."],key:["Rain and snow that lands on the hills around it. Reads “It is fed by rain and snow that lands on the hills all around it.” (RI.3.1)","The land that water runs down from. Reads “All that land together is called the lake's watershed.” (RI.3.1)","About half a square mile for the lake, and about nine square miles for the watershed. (RI.3.1)","In the lake. Reads “Every drop that falls on those hills runs downhill, and the low place it runs to is the lake.” (RI.3.1)","Asks a question Text 2 can answer, such as: How far back from the shore does camp wash dishes? What goes in a covered bin? Why are the shore plants left standing? (RI.3.1, asks questions)"]},{title:"Same and Different",std:["RI.3.9"],n:3,dur:95,dir:"Think about both texts. Answer out loud.",desc:"comparing and contrasting two texts on the same topic",html:()=>lookBack("the two texts",twoTexts()),qs:["Both texts are about the water in Pine Lake. What is the same in both texts? What is different?","Say the most important point of Text 1 in one sentence. Then say the most important point of Text 2 in one sentence."],key:["Same: both texts are about the watershed, and both say that water runs downhill off the land and ends up in the lake. (RI.3.9, compare)","Different: Text 1 explains where the lake's water comes from and how much bigger the watershed is than the lake. Text 2 gives camp's rules so that soap, scraps, and soil do not wash in. (RI.3.9, contrast)","Text 1: the lake's water comes from rain and snow landing on a watershed many times the size of the lake itself, and every drop that falls on that land runs down into the lake. Text 2: because everything on that land ends up in the lake, camp keeps soap, scraps, and soil back from the shore. Both points is the full response. Partial: one of the two most important points given, or a small detail offered in place of the main point, is approaching. (RI.3.9, most important points)"]}]},{id:5,title:"Watershed Notes",short:"Notes",parts:[{std:["W.3.8"],n:3,label:"checks met",dur:95,dir:"Look back at the two texts. Write your notes on your paper and hold it up.",desc:"taking brief notes from two texts and sorting them into given categories",html:()=>`${twoTexts()}<p class="big">Make two boxes on your paper. Label them like the boxes below. Write two short notes from the texts in each box.</p>${noteBoxes("Where the water comes from","What camp does about it")}<p class="small" style="text-align:center;font-size:1.2rem">A note is just a few words. You do not need a whole sentence.</p>`,key:["Water box: two facts from Text 1, such as fed by rain and snow, water runs downhill, the low place is the lake, watershed is all that land, nine square miles of watershed. (W.3.8, sorts evidence into the given category)","Camp box: two facts from Text 2, such as wash dishes thirty steps back, soapy water soaks into the ground, scraps in a covered bin, leave the shore plants, roots hold the soil. (W.3.8, sorts evidence into the given category)","Notes are brief: a few words or a short phrase, not a whole sentence copied out of the text. (W.3.8, brief notes)"]}]},{id:6,title:"Listen to the Plan",short:"Listen",parts:[{std:["SL.3.2"],n:5,dur:110,dir:"Listen while your teacher reads. Then answer out loud. For the last two, use the graph.",desc:"main ideas and supporting details from a text read aloud and from a graph",read:PLAN_READ,html:()=>`<p class="big" style="margin-top:0">Your teacher will read you a short report about how camp plans a paddle day. Listen for the big idea and for the details that back it up. Then look at the graph.</p>`,fig:()=>F.row([F.barGraph({title:"Life jackets at camp",cats:["Small","Medium","Large"],vals:[10,24,14],max:28,step:4}),"How many jackets camp keeps in each size"]),qs:["What is the main idea of the report your teacher read?","Give two details from the report that back up that main idea.","What are the three things that go into the plan?","Look at the graph. What is the main idea the graph shows?","Give one supporting detail from the graph."],key:["Main idea: camp plans a paddle day the night before instead of deciding in the morning, so the morning runs smoothly. (SL.3.2, main idea of a text read aloud)","Any two details: the counselors read the weather; a windy forecast moves the paddle; they count the life jackets and match a size to every paddler; nobody goes out without one that fits; they pick a short route or a long route; the plan goes on the board by bedtime. (SL.3.2, supporting details)","The weather, the life jackets, and the route. (SL.3.2, supporting details)","Camp does not keep the same number of jackets in each size. It keeps far more mediums than anything else. (SL.3.2, main idea presented visually and quantitatively)","Any detail read correctly from the graph: 24 medium jackets, 14 large, 10 small, small is the fewest size, or the 24 mediums exactly match the small and large counts added together, since 10 + 14 = 24. (SL.3.2, supporting detail presented quantitatively)"]}]},{id:7,title:"Tell Me About It",short:"Tell Me",parts:[{std:["SL.3.4"],n:3,label:"checks met",dur:75,dir:"Talk for about one minute. Speak clearly.",desc:"reporting on a topic with facts and details, speaking clearly",html:()=>`<p class="huge" aria-hidden="true">${F.icon("pine",96)}</p><p class="big">Tell me about a place outdoors that you know well. It can be a park, a yard, a trail, or anywhere you have been more than once.</p>${pills("Where it is","Facts","Details")}`,key:["Gives facts that fit the place and stay on the topic (SL.3.4)","Adds relevant, descriptive details, such as what is there, what it looks like, or what you can do there (SL.3.4)","Speaks clearly at a pace you can follow (SL.3.4)"]}]},{id:8,title:"Fix the Camp Notice",short:"Fix It",parts:[{std:["L.3.1"],n:7,dur:90,dir:"Each line has one thing to fix or finish. Say the whole line out loud the right way.",desc:"spoken grammar items (plurals, verb tense, agreement, comparing words, pronouns, conjunctions, adverbs)",qs:["The childs carried the paddles down to the dock.","Yesterday we swimmed across the little cove.","Four canoes was tied along the dock.","This is the most quietest morning all week.","Nadia found her hat, but she lost their water bottle.","Join these two sentences into one. Use because: We ate early. The paddle started at seven.","Which word fits? The canoe glided ____ across the flat water. Is it quiet or quietly?"],key:["The children carried the paddles down to the dock. (L.3.1, irregular plural noun)","Yesterday we swam across the little cove. (L.3.1, irregular past tense verb)","Four canoes were tied along the dock. (L.3.1, subject-verb agreement)","This is the quietest morning all week. (L.3.1, superlative adjective)","Nadia found her hat, but she lost her water bottle. (L.3.1, pronoun that matches its noun)","We ate early because the paddle started at seven. (L.3.1, subordinating conjunction that joins a cause to a result)","quietly (L.3.1, adverb that tells how)"]}]},{id:9,title:"Groups and Shares",short:"Groups",parts:[{title:"Multiply",std:["3.OA.A.1"],n:3,dur:60,dir:"Look at the acorns. Write your equation on your paper and hold it up. Say your story problem out loud.",desc:"explaining multiplication as equal groups",html:()=>`<p class="big" style="margin-top:0">The squirrels left a tidy pile of acorns on the dock, lined up in rows.</p>`,fig:()=>F.row([F.array(4,6,"acorn"),"Acorns on the dock"]),qs:["Write a multiplication equation for this picture. What does each number mean?","Tell a story problem for 5 × 7.","There are 3 tents and 4 campers sleep in each tent. What does 3 × 4 mean here, and what is the answer?"],key:["4 × 6 = 24. There are 4 rows with 6 acorns in each row, 24 in all. 6 × 4 = 24, read as 6 columns of 4, is also correct. Partial: the equation right with no meaning for each number is approaching. (3.OA.A.1)","A story with 5 equal groups of 7, or 7 groups of 5, and 35 in all. Partial: a story with the right numbers but no equal groups is approaching. (3.OA.A.1)","3 groups of 4, which is 3 tents with 4 campers in each tent, so 12 campers. Partial: 12 given with no account of what 3 × 4 means is approaching. (3.OA.A.1)"]},{title:"Divide",std:["3.OA.A.2"],n:3,dur:55,dir:"Answer out loud. For the first one, say your whole story problem.",desc:"explaining division as equal shares or equal groups",qs:["Tell a story problem for 24 ÷ 6. What does the answer mean in your story?","18 paddles are put into 3 racks with the same number in each rack. What does 18 ÷ 3 = 6 mean here?","20 logs are tied into bundles of 5 logs each. What does 20 ÷ 5 = 4 mean here?"],key:["A story where 24 things are shared into 6 equal groups, or put into groups of 6, and the answer 4 is named as either the number in each group or the number of groups, to match the story. Partial: a story with the right numbers but no equal sharing is approaching. (3.OA.A.2)","6 paddles go in each rack. The 3 is the number of groups and the 6 is how many are in each group. Partial: 6 given with no account of what it counts is approaching. (3.OA.A.2, equal shares)","There are 4 bundles. Here the 5 is how many are in each group, so the answer counts the groups. Partial: 4 given with no account of what it counts is approaching. (3.OA.A.2, equal groups)"]}]},{id:10,title:"Round the Camp Counts",short:"Round It",parts:[{std:["3.NBT.A.1"],n:5,dur:55,dir:"Say each answer out loud.",desc:"rounding whole numbers to the nearest 10 and the nearest 100",qs:["Round 68 to the nearest 10.","Round 435 to the nearest 10.","Round 435 to the nearest 100.","Round 750 to the nearest 100.","Round 92 to the nearest 10."],key:["70. Partial: 60 rounds down when the ones digit is 8 and does not count. (3.NBT.A.1)","440. It sits exactly halfway, and the rule is to round up. Partial: 430 rounds down at the halfway mark and does not count. (3.NBT.A.1)","400, because 435 is closer to 400 than to 500. Partial: 500 rounds up when 435 sits below 450 and does not count. (3.NBT.A.1)","800. It sits exactly halfway between 700 and 800, so round up. Partial: 700 rounds down at the halfway mark and does not count. (3.NBT.A.1)","90. Partial: 100 rounds up when the ones digit is 2 and does not count. (3.NBT.A.1)"]}]},{id:11,title:"Two-Step Camp Problems",short:"Two Steps",parts:[{std:["3.OA.D.8"],n:5,dur:130,dir:"Solve on your paper. Show your work and hold it up.",desc:"two-step word problems with an equation and an estimate",qs:["The camp store has 4 boxes of fire starters with 9 in each box. The cooks use 7 of them. How many are left? Write an equation with a letter for the unknown. Then solve.","The pantry had 236 cans of soup, and a truck brought 185 more. Then 97 cans were used. How many are left? Estimate first. Then solve.","Six canoes go out with 3 campers in each one. Then 5 more campers get into the big canoe. How many campers are on the water?"],key:["Problem 1 equation with a letter: 4 × 9 − 7 = n, or 4 × 9 = 36 and 36 − 7 = n. Partial: the right answer with no letter for the unknown is approaching. (3.OA.D.8)","Problem 1 answer: 29 fire starters. Partial: 36 stops at the boxes and leaves the 7 out, so it is approaching. (3.OA.D.8)","Problem 2 estimate: about 200 + 200 − 100 = 300 cans. Partial: any rounding that lands near 320 counts, and no estimate at all is approaching. (3.OA.D.8, rounding to check a reasonable answer)","Problem 2 answer: 236 + 185 = 421, then 421 − 97 = 324 cans. Partial: 421 stops before the cans are used and is approaching. (3.OA.D.8)","Problem 3 answer: 6 × 3 = 18, then 18 + 5 = 23 campers. Partial: 18 stops at the six canoes and leaves the 5 out, so it is approaching. (3.OA.D.8)"]}]},{id:12,title:"Tile the Campsite",short:"Tiles",parts:[{std:["3.MD.C.7"],n:6,dur:100,dir:"Answer out loud. For numbers 3 and 4, write your work on your paper. Then hold it up.",desc:"relating the area of a rectangle to multiplication and addition",html:()=>`<p class="big" style="margin-top:0">Camp is laying square pavers on the ground at the campsites so the tents stay dry. Every paver is 1 square meter.</p>`,fig:()=>`<div class="figure" style="gap:30px;align-items:flex-end">${group(F.gridRect(5,7,0,{cell:38}),"Paved corner")}${group(splitRect(4,3,5),"Split path")}</div>`,qs:["Look at the paved corner. How many pavers cover it? Write the multiplication equation that matches the picture.","A tent pad is 4 meters by 6 meters. What is its area? Say the unit.","Look at the split path. Find the area of the blue block and the area of the gold block. Then add them. Now multiply the whole length by the whole width. Do you get the same answer?","The cook tent sits on an L shaped pad. Use the picture below. What is the total area?","One tarp is 8 feet by 5 feet. Another tarp is 6 feet by 7 feet. Which tarp covers more, and by how much?","A rectangle has an area of 42 square feet. One side is 6 feet long. How long is the other side?"],fig2:()=>F.row([ellSite(),"The L shaped cook tent pad, in square meters"]),key:["35 pavers. 5 × 7 = 35, or 7 × 5 = 35. The picture shows 5 rows of 7 pavers. Partial: the count right with no multiplication equation written is approaching. (3.MD.C.7)","24 square meters. 4 × 6 = 24. The unit has to be square meters, not meters. Partial: 24 with no square unit named is approaching. (3.MD.C.7)","Blue block 4 × 3 = 12. Gold block 4 × 5 = 20. 12 + 20 = 32. The whole rectangle is 4 × 8 = 32. Yes, the two ways match. Partial: the two blocks right with no whole-rectangle check is approaching. (3.MD.C.7, area of a 4 by 3 plus 5 rectangle is 4 × 3 plus 4 × 5)","23 square meters. The bottom block is 7 × 2 = 14 and the block on top is 3 × 3 = 9, then 14 + 9 = 23. Area adds up when a shape is cut into rectangles that do not overlap. Partial: one of the two blocks worked out is approaching. (3.MD.C.7)","The 6 by 7 tarp, by 2 square feet. 8 × 5 = 40 square feet and 6 × 7 = 42 square feet. Partial: naming the tarp with no difference given is approaching. (3.MD.C.7)","7 feet, because 6 × 7 = 42. Partial: 36 from taking 42 − 6 subtracts where the problem divides and does not count. (3.MD.C.7)"]}]},{id:13,title:"Fraction Tarps",short:"Tarps",parts:[{title:"Name the Fraction",std:["3.NF.A.1"],n:5,dur:60,dir:"Look at the two strips. Answer out loud.",desc:"naming a fraction and a unit fraction of a whole, and telling when parts are not equal",html:()=>`<p class="big" style="margin-top:0">Camp cuts long strips of canvas for tarp patches. Strip A and Strip B are the same size to start with.</p>`,fig:()=>`<div class="figure" style="gap:26px;align-items:flex-end">${group(splitBar([0,.25,.5,.75,1],3),"Strip A")}${group(splitBar([0,.12,.38,.76,1],0),"Strip B")}</div>`,qs:["Strip A: what fraction is shaded? What fraction of the whole strip is one part?","Strip B is cut into 4 parts. Is it cut into fourths? Tell why or why not.","A rope is cut into 6 equal pieces. What fraction of the whole rope is one piece?","In the fraction 5/8, what does the 8 tell you? What does the 5 tell you?"],key:["3/4 is shaded, and one part is 1/4 of the whole strip. Partial: one of the two fractions given is approaching. (3.NF.A.1)","No. The 4 parts are not the same size, and fourths have to be 4 equal parts of the whole. Partial: saying no with nothing said about equal parts is approaching. (3.NF.A.1)","1/6. The whole rope is cut into 6 equal parts, so one part is 1 of those 6. Partial: 6 given with no fraction form is approaching. (3.NF.A.1)","The 8 tells you the whole is cut into 8 equal parts. Partial: naming the 8 parts with nothing said about them being equal is approaching. (3.NF.A.1)","The 5 tells you how many of those 1/8 parts you have. Partial: naming 5 parts with no account of their size is approaching. (3.NF.A.1)"]},{title:"Equal Parts",std:["3.G.A.2"],n:4,dur:55,dir:"Draw on your paper for the first one and hold it up. Answer the rest out loud.",desc:"cutting shapes into parts with equal areas and naming one part as a unit fraction of the whole",fig:()=>F.row([F.fracCircle(3,0,180),"The round pan lid"]),qs:["On your paper, draw a rectangle and cut it into 6 parts with equal areas. What fraction of the whole is each part?","The round pan lid in the picture is cut into equal parts. What fraction of the whole lid is one part?","Tell your teacher two different ways to cut a square tarp into 4 parts with equal areas. What fraction of the square is each part?"],key:["Draws 6 parts that are about equal in area. Strips, a 2 by 3 grid, or 6 rows all count. Partial: 6 parts drawn that are plainly not equal in area is approaching. (3.G.A.2)","Each part is 1/6 of the rectangle. Partial: 6 given with no fraction form is approaching. (3.G.A.2)","1/3. The lid is cut into 3 parts with the same area. Partial: 3 given with no fraction form is approaching. (3.G.A.2)","Any two correct ways, such as 4 strips side by side, a 2 by 2 grid of smaller squares, 4 rows across, or two cuts corner to corner making 4 triangles. Each part is 1/4 of the square. Partial: one correct way given is approaching. (3.G.A.2)"]}]},{id:14,title:"The Buoy Line",short:"Buoy Line",parts:[{title:"On the Line",std:["3.NF.A.2"],n:5,dur:65,dir:"Look at the lines. Answer out loud. Tell how you know.",desc:"naming a fraction as a number on a number line and counting unit fractions from 0",html:()=>`<p class="big" style="margin-top:0">A swim line runs from the dock out to a float. The 0 is the dock and the 1 is the float. Buoys are tied along it.</p>`,fig:()=>stackFig(group(F.numberLine({min:0,max:1,step:.125,hideNumbers:true,ticks:[[0,"0"],[1,"1"]],labels:{.125:"A",.375:"B",.75:"C"},width:560}),"Line 1, cut into 8 equal parts")+group(F.numberLine({min:0,max:3,step:1/3,labelEvery:1,marks:[5/3],width:560}),"Line 2, cut into thirds")+group(F.numberLine({min:0,max:1,step:.2,hideNumbers:true,ticks:[[0,"0"],[1,"1"]],marks:[.4],width:560}),"Line 3, cut into 5 equal parts")),qs:["Line 1 is cut into 8 equal parts. What fraction is at buoy A?","What fraction is at buoy B on Line 1?","What fraction is at buoy C on Line 1?","Line 2 runs from 0 to 3 and is cut into thirds. Name the fraction at the dot.","Line 3 is cut into 5 equal parts. How many jumps of 1/5 does it take to reach the dot from 0. What fraction is that?"],key:["1/8. It is at the end of the first of 8 equal parts from 0. Partial: 8 given with no fraction form is approaching. (3.NF.A.2)","3/8. Count 3 equal parts from 0. Partial: counting ticks from the 0 instead of parts gives 2/8 and does not count. (3.NF.A.2)","6/8. Accept 3/4, which names the same point. Count 6 equal parts from 0. Partial: counting ticks from the 0 instead of parts gives 5/8 and does not count. (3.NF.A.2)","5/3. Accept 1 2/3. Counting thirds from 0 gives 1/3, 2/3, 3/3, 4/3, 5/3, and the dot is on the fifth one. Partial: 5/9 treats the whole 0 to 3 line as one whole and does not count. (3.NF.A.2)","2 jumps, which lands on 2/5. Partial: one of the count of jumps and the fraction given is approaching. (3.NF.A.2)"]},{title:"Which Is More?",std:["3.NF.A.3"],n:6,dur:85,dir:"Answer out loud. Tell how you know. You can draw on your paper to show your thinking.",desc:"explaining equivalent fractions and comparing fractions by reasoning about their size",html:()=>`<p class="big" style="margin-top:0">The cooks write down how full each water jug is as a fraction. Bar A and Bar B below are the same size. So they stand for two jugs that are the same size.</p>`,fig:()=>`<div class="figure" style="gap:28px;align-items:flex-end">${group(F.fracBar(2,1,{width:300}),"Bar A")}${group(F.fracBar(6,3,{width:300}),"Bar B")}</div>`,qs:["Which is more water in the same jug, 3/4 or 3/8? How do you know?","Which is more, 5/6 of a jug or 2/6 of the same jug? How do you know?","Look at Bar A and Bar B. Are the shaded parts equal? Say it as two fractions that are equal.","Name a fraction that is equal to 2/4.","Write 1 whole as a fraction with 3 as the bottom number. Then write the whole number 6 as a fraction.","Two jugs are not the same size. Ana says 1/2 of the small jug is more than 1/2 of the big jug. Can you compare those two halves? Tell why or why not."],key:["3/4. The top numbers are the same, so compare the piece sizes: fourths are bigger pieces than eighths, so 3 fourths is more than 3 eighths. Partial: naming 3/4 with no reason about the size of the pieces is approaching. (3.NF.A.3)","5/6. The pieces are the same size, so the one with more pieces is more. Partial: naming 5/6 with no reason is approaching. (3.NF.A.3)","Yes, they are equal. 1/2 = 3/6. The bars are the same size and the shaded parts cover the same amount. Partial: saying yes with no pair of equal fractions written is approaching. (3.NF.A.3)","1/2. Also correct: 3/6, 4/8. Partial: 2/4 given back does not count, since a different name is what is asked. (3.NF.A.3)","3/3 and 6/1. Partial: one of the two given is approaching. (3.NF.A.3)","No. Fractions can only be compared when they name parts of the same whole. The jugs are different sizes, so 1/2 of one is not the same amount as 1/2 of the other, and the fractions alone cannot settle it. Partial: saying no with nothing said about the same whole is approaching. (3.NF.A.3)"]}]},{id:15,title:"Measure and Plot",short:"Measure",parts:[{title:"Measure It",std:["3.MD.B.4"],n:3,dur:105,dir:"Look at the rulers. Each ruler shows inches. Say each length out loud. For the last one, get a ruler and measure.",mats:["a ruler"],desc:"measuring lengths to the nearest half and fourth of an inch, including generating measurements of real objects with a ruler",fig:()=>F.row([F.ruler({length:5,px:90,item:3.5,itemLabel:"Stick A",parts:4}),"Ruler 1, marked in inches"],[F.ruler({length:5,px:90,item:2.25,itemLabel:"Stick B",parts:4}),"Ruler 2, marked in inches"]),qs:["How long is Stick A?","How long is Stick B?","Now you are the measurer. Find three small things at your table. Something like a pencil. Or an eraser. Or a paper clip. Measure each one with your ruler. Say what each thing is. Say how long it is, to the nearest quarter inch."],key:["3 1/2 inches. The stick ends on the half-inch mark between 3 and 4. Partial: 3 inches or 4 inches rounds to a whole and is approaching. (3.MD.B.4)","2 1/4 inches. The stick ends on the first small mark after 2. Partial: 2 inches rounds to a whole and is approaching. (3.MD.B.4)","Three objects of the student's own choosing, each measured and named with a length. Watch the 0 end of the ruler line up with the end of the object, and listen for a length to the nearest quarter inch (a whole, 1/4, 1/2, or 3/4) with the unit inches said. Write the three objects and lengths on the record sheet, and have the student hold one object on the ruler up to the camera so you can check that reading yourself. Or: any three objects count, since these are the student's own data and there is no fixed answer. Partial: three lengths given but all rounded to whole inches, or the ruler started at the 1 instead of the 0, is approaching. (3.MD.B.4)"]},{title:"Plot It",std:["3.MD.B.4"],n:3,dur:45,dir:"Look at the table and the empty line plot. Tell your teacher where every X goes.",desc:"showing measurement data on a line plot marked in fourths of an inch",html:()=>`<p class="big" style="margin-top:0">Camp measured six sticks of kindling. Sticks A and B are the two you just measured. Tell your teacher where each X goes on the plot.</p><div class="figure">${F.table(["Stick","A","B","C","D","E","F"],[["Length in inches","3 1/2","2 1/4","3","3","2 3/4","3"]])}</div>`,fig2:()=>F.row([F.linePlot({min:2,max:4,step:.25,counts:{},labels:{2.25:"2 1/4",2.5:"2 1/2",2.75:"2 3/4",3.25:"3 1/4",3.5:"3 1/2",3.75:"3 3/4"},title:"Kindling lengths in inches",width:620}),"The empty plot"]),qs:["Where do the Xs go for the three sticks that measured exactly 3 inches?","Where do the Xs go for Stick A and Stick B?","Where does the X go for Stick E? How many Xs are on the finished plot?"],key:["Three Xs stacked above the 3, one each for Sticks C, D, and F. Partial: two of the three Xs placed right is approaching. (3.MD.B.4)","One X above 3 1/2 for Stick A and one X above 2 1/4 for Stick B. If a stick was measured wrong in the part above, count the X as right when it matches the student's own measurement. Partial: one of the two Xs placed right is approaching. (3.MD.B.4)","One X above 2 3/4 for Stick E, and 6 Xs in all, one for each stick. Partial: the X placed right with no total count of Xs is approaching. (3.MD.B.4)"]}]},{id:16,title:"Camp Writer",short:"Write",parts:[{alt:{group:"write",key:"opinion",label:"Opinion",icon:"💬",hint:"Canoes or a roof?"},std:["W.3.1","L.3.1"],n:5,label:"checks met",dur:280,dir:WRITE_DIR,desc:"an opinion writing piece",html:()=>`<p class="big">Camp has saved enough money for one new thing this summer. It can buy four more canoes, or it can build a roof over the eating tables. More canoes would mean nobody has to wait for a turn on the lake. A roof would mean meals go on even in the rain.</p><p class="big">Which should camp pick? Write your opinion and give reasons. Write 4 or 5 sentences.</p>${checklist(["Say your opinion in the first sentence","Give two reasons for it","Use a linking word: because, since, also, for example","End with a closing sentence"])}`,key:["Introduces the topic and states a clear opinion about the canoes or the roof (W.3.1)","Gives reasons that support the opinion, such as no waiting for a turn, or meals going on in the rain (W.3.1)","Uses linking words such as because, since, also, for example, therefore (W.3.1)","Ends with a concluding sentence (W.3.1)","Writes complete sentences with correct verb tenses and subject-verb agreement (L.3.1)"]},{alt:{group:"write",key:"facts",label:"Explain",icon:"📘",hint:"Teach about the watershed"},std:["W.3.2","L.3.1"],n:5,label:"checks met",dur:280,dir:WRITE_DIR,desc:"an informative writing piece",html:()=>`<p class="big">Write to teach someone what a watershed is and why camp washes dishes away from the shore. Use facts from the two texts. Write 5 or 6 sentences.</p>${checklist(["Start with a sentence that names your topic","Give facts from the texts, and add a detail to at least one of them","Use linking words: also, another, because","End with a closing sentence"])}${lookBack("the two texts",twoTexts())}`,key:["Introduces the topic: what a watershed is and why it changes how camp washes dishes (W.3.2)","Develops the topic with facts from the texts, such as rain and snow landing on the hills, water running downhill into the lake, the watershed being nine square miles, soap travelling downhill with the rain, dishes washed thirty steps back, and roots holding the soil, and adds at least one detail (W.3.2)","Uses linking words such as also, another, and, because (W.3.2)","Ends with a concluding sentence (W.3.2)","Writes complete sentences with correct verb tenses and subject-verb agreement (L.3.1)"]},{alt:{group:"write",key:"story",label:"Story",icon:"✨",hint:"A calm morning on the water"},std:["W.3.3","L.3.1"],n:5,label:"checks met",dur:280,dir:WRITE_DIR,desc:"a narrative writing piece",html:()=>`<p class="big">Early on a calm morning you go down to a dock with someone in your family and take a canoe out on the flat water. Write the story of what you see and what happens out there. It can be real or made up. Write 5 or 6 sentences.</p>${pills("First","Next","After that","Finally")}${checklist(["Tell who is there and where it happens","Tell what happens in order","Add a detail that helps the reader picture it, and tell what someone says or feels","Give your story an ending"])}`,key:["Sets up the situation and who is in the story (W.3.3)","Events happen in a clear order, with time words such as first, next, after that, finally (W.3.3)","Uses descriptive details and tells thoughts or feelings, or uses dialogue (W.3.3)","Has an ending that wraps up the story (W.3.3)","Writes complete sentences with correct verb tenses and subject-verb agreement (L.3.1)"]}]},{id:17,title:"Watching from the Reeds",short:"Senses",parts:[{title:"Sense, Brain, Act",std:["3-LS1-1"],n:3,dur:90,dir:"Answer out loud. For the last one, draw your model on your paper and hold it up.",desc:"using a model to show how an animal takes in information, processes it, and responds",html:()=>`<p class="big">A heron stands dead still in the shallow water by the reeds. A minnow drifts past her feet. She does not move for the first two that go by. Then on the third she snaps her beak into the water and comes up with it.</p>
     <div class="figure">${F.icon("bluebird",96)}${F.icon("telescope",80)}${F.icon("fish",88)}</div>`,qs:["Which sense took in the information about the minnow?","She let two minnows pass and struck at the third. What was going on inside her while she waited?","Draw a labelled model of this in three stages. Put an arrow from each stage to the next."],key:["Sight, with her eyes, watching the water below her. (3-LS1-1)","Her brain was processing what her eyes sent in, judging how close and how deep each fish was, and deciding whether this was the one to strike at. (3-LS1-1)","Three parts in order with arrows: eyes or sees the minnow, then brain, then strikes. The order is what is rated. A model with nothing in the middle is incomplete. (3-LS1-1)"]},{title:"The School of Minnows",std:["3-LS2-1"],n:3,dur:75,dir:"Look at the table. Answer out loud.",desc:"building an argument from data that forming a group helps animals survive",html:()=>`<p class="big">Camp counted what happened to minnows in the shallows over a week of watching.</p>
     <table class="bigTable"><tr><th>Minnows</th><th>Bass attacks that caught a fish, out of 20</th><th>Minutes of feeding before hiding</th></tr>
     <tr><td>a minnow swimming alone</td><td>13</td><td>4</td></tr>
     <tr><td>a school of about three hundred</td><td>3</td><td>18</td></tr></table>`,qs:["Which minnows were caught less often?","Make an argument that swimming in a school helps a minnow survive. Use a number from the table.","A bass finds a school of three hundred minnows. That is much easier than finding a single minnow. So why is the school still a better deal?"],key:["the ones in the school, 3 catches out of 20 attacks against 13 (3-LS2-1)","The claim yes, with the numbers attached: only 3 of 20 attacks on the school caught a fish against 13 on the lone minnow, and the school fed for 18 minutes against 4. A yes with no number is not yet an argument. (3-LS2-1)","Being found is not the same as being caught. With three hundred fish swirling, the bass struggles to lock on to one, and each single minnow has only a small chance of being the one taken, so each one is safer than it would be alone. (3-LS2-1)"]}]},{id:18,title:"Ducklings and Sunflowers",short:"Traits",parts:[{title:"Passed Down and Shaped",std:["3-LS3-1","3-LS3-2"],n:4,dur:120,dir:"Look at both tables. Answer out loud.",desc:"reading trait data for parents and offspring, naming the variation, and telling when the surroundings shaped a trait",html:()=>`<p class="big">Table 1: a pair of ducks with a white ring at the neck, and their five ducklings grown up.</p>
     <table class="bigTable"><tr><th>Duck</th><th>Neck</th><th>Wing span in cm</th></tr>
     <tr><td>parent 1</td><td>white ring</td><td>82</td></tr><tr><td>parent 2</td><td>white ring</td><td>86</td></tr>
     <tr><td>young A</td><td>white ring</td><td>79</td></tr><tr><td>young B</td><td>white ring</td><td>88</td></tr>
     <tr><td>young C</td><td>white ring</td><td>83</td></tr><tr><td>young D</td><td>white ring</td><td>85</td></tr>
     <tr><td>young E</td><td>white ring</td><td>80</td></tr></table>
     <p class="big">Table 2: two sunflowers grown from seeds out of the same flower head.</p>
     <table class="bigTable"><tr><th>Plant</th><th>Where it grew</th><th>Height</th><th>Head width</th></tr>
     <tr><td>plant 1</td><td>open ground by the dock</td><td>230 cm</td><td>26 cm</td></tr>
     <tr><td>plant 2</td><td>in the shade of the boat shed</td><td>95 cm</td><td>9 cm</td></tr></table>`,qs:["Every young duck has a white neck ring, the same as both parents. Where did that trait come from?","The wing spans are all a little different. What is that difference called. Does it mean one of them is not theirs?","In Table 2 both seeds came out of the same flower head. What made one 230 cm and the other 95 cm?","So is a sunflower’s height decided only by the seed it came from? Explain."],key:["It was inherited from the parents. A trait both parents have and every offspring has is passed down. (3-LS3-1)","Variation. They are all still their young: inherited traits vary from one offspring to the next, so a group of similar organisms is not identical. (3-LS3-1)","How much sunlight each one got. Same flower head, different surroundings, different plant. (3-LS3-2)","No. The environment shaped it too. Listen for the idea that a trait can be influenced by where a living thing grows, not by inheritance alone. (3-LS3-2)"]}]},{id:19,title:"Stone and Survival",short:"Fossils",parts:[{title:"Clues in the Bluff",std:["3-LS4-1"],n:3,dur:90,dir:"Look at the table of rock layers. Answer out loud.",desc:"reading fossil data to say which organisms lived in a place and what the place was like",html:()=>`<p class="big">The bluff on the far shore of the lake shows three layers where the water has cut into it. Camp listed the fossils in each. The top layer is the youngest.</p>
     <table class="bigTable"><tr><th>Layer</th><th>Fossils found</th></tr>
     <tr><td>top</td><td>reed stems, pond snails, a small fish bone</td></tr>
     <tr><td>middle</td><td>pine needles, a beetle wing case</td></tr>
     <tr><td>bottom</td><td>reed stems, pond snails, a frog bone</td></tr></table>
     <div class="figure">${F.icon("snail",80)}${F.icon("pine",80)}${F.icon("fish",80)}</div>`,qs:["Name two organisms that once lived where this bluff now stands.","The bottom and the top layers both hold reeds and pond snails. What kind of place was it in both of those times? Use the fossils as your evidence.","The middle layer holds pine needles and a beetle but no water animals. What does that tell you happened in between?"],key:["Any two the table names: a reed, a pond snail, a fish, a pine, a beetle, a frog. (3-LS4-1)","A pond or lake edge, fresh water with plants growing in it. Reeds, pond snails, a fish and a frog all need standing fresh water, and naming them is the evidence. (3-LS4-1)","The water was gone for a while and the place was dry pine forest, and then later the water came back. A place can change and then change back. (3-LS4-1)"]},{title:"A Useful Difference",std:["3-LS4-2"],n:3,dur:90,dir:"Look at the table. Answer out loud.",desc:"explaining how a variation among individuals of one species gives an advantage",html:()=>`<p class="big">Dragonflies hunt small flies over the lake. Camp measured wings and counted catches.</p>
     <table class="bigTable"><tr><th>Dragonflies</th><th>Wing span</th><th>Flies caught in an hour</th><th>Caught by a bird, out of 30</th></tr>
     <tr><td>shorter wings</td><td>5 cm</td><td>9</td><td>11</td></tr>
     <tr><td>longer wings</td><td>8 cm</td><td>26</td><td>4</td></tr></table>`,qs:["Which dragonflies caught more flies in an hour?","Explain why a longer wing is an advantage for a dragonfly over this lake. Use the table.","The longer-winged dragonflies also left more eggs behind. How can a trait that helps a dragonfly hunt and dodge end up giving it more young?"],key:["the longer-winged dragonflies, 26 flies against 9 (3-LS4-2)","Longer wings make it a faster, more agile flier, so it catches more flies, 26 against 9, and it is caught by birds less often, 4 of 30 against 11. The explanation has to lean on the data. (3-LS4-2)","It gets more food and lives longer, so it has more chances to find a mate and lay eggs. Accept any version that links surviving to finding mates or reproducing. (3-LS4-2)"]}]},{id:20,title:"The Lake Dropped",short:"Habitat",parts:[{title:"Who Survives, and What Would Help",std:["3-LS4-3","3-LS4-4"],n:4,dur:120,dir:"Read the table. Answer out loud.",desc:"arguing from data who can survive in a changed habitat, then judging the merit of a solution",html:()=>`<p class="big">A hot dry summer dropped the lake by a meter. The shallows warmed, and the water held less of the air that fish breathe. Camp surveyed the shore before and after.</p>
     <table class="bigTable"><tr><th>Living thing</th><th>Before</th><th>After</th></tr>
     <tr><td>green algae in the shallows</td><td>a light film</td><td>thick mats across the warm shallows</td></tr>
     <tr><td>yellow perch</td><td>common in the shallows</td><td>few left, and only out in the deeper water</td></tr>
     <tr><td>cold-water trout</td><td>28 counted</td><td>none counted anywhere in the lake</td></tr></table>`,qs:["Which living thing survived well after the lake dropped? Give the evidence.","Which one could not survive in the lake at all. Which one only did less well?","Camp suggests planting shade trees along the south shore to cool the shallows. Would that help the trout? Name one drawback.","A second plan is to run a pump that bubbles air into the deep water. Which plan has more merit, and why?"],key:["The green algae. It went from a light film to thick mats, so warm shallow water suited it. (3-LS4-3)","The cold-water trout could not survive at all, from 28 down to none. The yellow perch survived less well, few left and only in deeper water. (3-LS4-3)","Shade would cool a strip of the shallows a little, but the trout need the whole lake cooler, so it would help only a small part of the problem. Then any real drawback: trees take years to grow, they shade only the edge, they do nothing about the air in the water. A claim with no drawback is half of this standard. (3-LS4-4)","Either plan can earn credit. What is rated is the reasoning: the pump puts air back into the water that fish breathe and works right away, but it needs power and someone to run it forever, while the trees cost nothing to run and last but help only the edge and take years. (3-LS4-4)"]}]},{id:21,title:"Weather and Climate",short:"Weather",parts:[{title:"A Season of Weather",std:["3-ESS2-1"],n:3,dur:90,dir:"Look at the table. Answer out loud. For the last one, draw your graph on your paper and hold it up.",desc:"reading and making a graphical display of typical weather for one season",html:()=>`<p class="big">Camp records the highest temperature of each week through the summer season.</p>
     <table class="bigTable"><tr><th>Week</th><th>Highest temperature</th></tr>
     <tr><td>1</td><td>27 C</td></tr><tr><td>2</td><td>31 C</td></tr><tr><td>3</td><td>34 C</td></tr>
     <tr><td>4</td><td>36 C</td></tr><tr><td>5</td><td>33 C</td></tr><tr><td>6</td><td>29 C</td></tr></table>
     <div class="figure">${F.icon("sun",88)}${F.icon("thermometer",88)}</div>`,qs:["Which week was hottest, and which two weeks were coolest?","Describe the shape of this season in one sentence. Say it as if you were telling a family. What should they expect?","Draw a bar graph of the six weeks. Label both sides."],key:["hottest week 4 at 36 C, coolest weeks 1 at 27 C and 6 at 29 C (3-ESS2-1)","It warms up for about four weeks, peaks in the middle of the season, then cools off again, with typical weeks in the low thirties. Any description that uses the table and gives the whole season rather than one week. (3-ESS2-1)","Six bars in week order with heights that match 27, 31, 34, 36, 33 and 29, a label on the week side and a label on the temperature side. A graph with no labels is incomplete. (3-ESS2-1)"]},{title:"Two Parts of the World",std:["3-ESS2-2"],n:3,dur:75,dir:"Look at the table. Answer out loud.",desc:"combining information to describe the climates of two different regions of the world",html:()=>`<p class="big">Two regions, both with hot summers, but with very different air.</p>
     <table class="bigTable"><tr><th>Region</th><th>Summer high</th><th>Damp in the air</th><th>Summer rain</th></tr>
     <tr><td>a dry inland region</td><td>38 C</td><td>low</td><td>2 cm</td></tr>
     <tr><td>a humid southern region</td><td>34 C</td><td>high</td><td>46 cm</td></tr></table>
     <div class="figure">${F.icon("sun",80)}${F.icon("rain",80)}</div>`,qs:["Which region has the higher summer high?","Both are hot, so what makes their summers feel so different? Use the table.","Give one reason why two regions of the world end up with different climates."],key:["the dry inland region, 38 C against 34 C (3-ESS2-2)","The damp. The humid region holds a lot of moisture in the air and gets 46 cm of summer rain, so it feels sticky and storms often, while the dry region has low damp and 2 cm of rain, so it feels baking and clear. (3-ESS2-2)","Any sound reason: how near a region is to the middle of the globe, how near it is to an ocean or a warm sea, how high it sits above sea level, whether mountains block the rain, which way the wind usually blows. (3-ESS2-2)"]},{title:"Ready for the Heat",std:["3-ESS3-1"],n:3,dur:90,dir:"Answer out loud.",desc:"making a claim about the merit of a design that reduces the impact of a weather hazard",html:()=>`<p class="big">On the hottest afternoons the open field at camp has no shade. Children get overheated. Camp puts up a wide cloth sail on four poles. It covers the middle of the field. A water station sits underneath it.</p>
     <div class="figure">${F.icon("sun",88)}${F.icon("umbrella",88)}</div>`,qs:["Which weather hazard is this design meant to reduce?","Make a claim. Does the shade sail and water station have merit? Give your reason.","Name one thing the sail and the water station do not protect against."],key:["extreme heat on the open field (3-ESS3-1)","Yes, with a reason attached: the sail blocks the direct sun so the air under it is cooler, and the water station lets people drink before they get overheated. A yes with no reason is not yet a claim. (3-ESS3-1)","Any real limit: heat away from the sail, very high air temperature even in shade, a thunderstorm, wind that could take the sail down, smoke, how few people fit underneath. (3-ESS3-1)"]}]},{id:22,title:"Ropes at the Dock",short:"Forces",parts:[{title:"Balanced or Not",std:["3-PS2-1"],n:4,dur:105,dir:"Answer out loud.",desc:"planning an investigation of balanced and unbalanced forces acting on an object",html:()=>`<p class="big">A canoe floats beside the dock with a rope tied to a post at the bow and another at the stern. Both ropes are tight. The canoe sits still even when the wind blows along the shore.</p>
     <div class="figure">${F.icon("canoe",96)}${F.icon("anchor",80)}</div>`,qs:["Are the forces on the canoe balanced or unbalanced? How do you know?","The stern rope is untied and the wind is blowing along the shore. What happens, and what changed about the forces?","Plan an investigation to find out. Is a loaded canoe harder to pull along the dock? Harder than an empty one? What will you change? What will you measure?","Name the things you would leave untouched between one run and the next."],key:["Balanced. The two ropes pull in opposite directions with equal force, and the canoe staying still is the evidence. (3-PS2-1)","The stern swings out and the canoe drifts along the dock. Nothing balances the push of the wind at that end now, so the forces are unbalanced. (3-PS2-1)","A plan with one thing changed and one thing measured: load the canoe with a known weight for each run (the change) and read a pull scale on the rope, or time the pull along a marked stretch of dock (the measure). (3-PS2-1)","Any controlled variable that fits the plan: the same canoe, the same rope and grip, the same stretch of dock, the same puller, a calm day or the same wind. (3-PS2-1)"]},{title:"Predict the Next Buoy",std:["3-PS2-2"],n:3,dur:90,dir:"Look at the table. Answer out loud.",desc:"using a pattern in motion data to predict where an object will be later",html:()=>`<p class="big">Buoys are anchored every 25 m out from the dock. A counselor paddles out at a steady stroke and the time is called as she passes each one.</p>
     <table class="bigTable"><tr><th>Buoy</th><th>Seconds since the dock</th></tr>
     <tr><td>1</td><td>20</td></tr><tr><td>2</td><td>40</td></tr><tr><td>3</td><td>60</td></tr></table>`,qs:["What pattern is in the table?","There are 6 buoys. When should she pass the last one. How far out is that in meters?","What could happen on the lake that would make your prediction wrong?"],key:["One buoy every 20 seconds, the same time for each one. She is moving at a steady speed. (3-PS2-2)","at 120 seconds, which is 150 m out, because 6 buoys at 20 seconds each is 120 seconds and 6 buoys at 25 m each is 150 m. Both parts have to be there. (3-PS2-2)","A new force acting on the canoe: a headwind or a tailwind, a current, she paddles harder or rests, waves from another boat, her canoe takes on water. A pattern only predicts while nothing changes. (3-PS2-2)"]}]},{id:23,title:"Pulling Without Touching",short:"Magnets",parts:[{title:"Ask About the Pull",std:["3-PS2-3"],n:3,dur:90,dir:"Answer out loud. Your two questions have to be questions, not statements.",desc:"asking questions about cause and effect in magnetic interactions between objects not touching",html:()=>`<p class="big">A steel fish hook has slipped into a crack. The crack is between two dock boards. It is just out of reach. A magnet is lowered on a string above the crack. That makes the hook rise. It sticks to the magnet. This happens without the magnet ever going into the crack.</p>
     <div class="figure">${F.icon("key",88)}${F.icon("anchor",80)}</div>`,qs:["The magnet never reaches into the crack, yet the hook comes up. What does that tell you about this force?","Come up with two questions about it that you could investigate.","The same magnet does nothing to a plastic lure in the same crack. What does that tell you about which materials this force acts on?"],key:["The force acts across a distance, with no contact between the objects. (3-PS2-3)","Any two real investigable questions: how deep can the crack be before the magnet stops lifting the hook, does a heavier hook still rise, does a brass hook rise, does lake water change it, does a bigger magnet reach further. A statement is not a question, so ask once more. (3-PS2-3)","A magnet pulls steel and iron, not plastic, so the force depends on what the object is made of. (3-PS2-3)"]},{title:"A Problem for a Magnet",std:["3-PS2-4","3-5-ETS1-1"],n:4,dur:105,dir:"Answer out loud. For the third one you may write your two sentences on your paper.",desc:"defining a design problem that magnets can solve, with criteria for success and constraints",html:()=>`<p class="big">Steel fish hooks drop between the dock boards all summer. Bare feet find them, and nobody can reach a hand into a crack that narrow.</p>
     <div class="figure">${F.icon("key",80)}${F.icon("anchor",80)}${F.icon("swim",72)}</div>`,qs:["Say what the problem is in one sentence. Open with: The problem is.","Why is a magnet a sensible idea here? Would the same tool pull up a dropped plastic bobber?","Write two things the tool must do if it is going to count as a success.","You may use three things only. A paddle, one magnet, and a length of fishing line. It has to be used from a kneeling position. You are on the dock. What limits does that put on your design?"],key:["A problem statement about getting steel hooks out of the cracks between dock boards so nobody steps on one. The problem has to be about the hooks in the cracks, not about fishing. (3-PS2-4)","The hooks are steel, and a magnet pulls steel without touching it, so it reaches into a crack too narrow for a hand. A plastic bobber is not pulled by a magnet, so no. (3-PS2-4)","Two criteria, written as what the tool must do: lift every hook out, fit over or into the narrow crack, hold the hooks while you raise it, work without anyone reaching in, be quick enough to do the whole dock. (3-5-ETS1-1)","Names the limits as limits: only three materials, only one magnet, and it has to work from kneeling on the dock, which limits how long and how heavy it can be. Materials, time, cost and the way it is used are all real constraints. (3-5-ETS1-1)"]}]},{id:24,title:"Compare and Test",short:"Design",parts:[{title:"Three Ways to Do It",std:["3-5-ETS1-2"],n:3,dur:90,dir:"Look at the table and the three rules. Answer out loud.",desc:"comparing several possible solutions against stated criteria and constraints",html:()=>`<p class="big">Water has to be carried from the pump up the hill to the tents. Three carriers were tried on the same walk.</p>
     <table class="bigTable"><tr><th>Design</th><th>Holds</th><th>Water left at the top</th><th>Cost</th></tr>
     <tr><td>open bucket</td><td>10 L</td><td>7 L</td><td>5 dollars</td></tr>
     <tr><td>jug with a screw lid</td><td>8 L</td><td>8 L</td><td>9 dollars</td></tr>
     <tr><td>backpack bladder with a cap</td><td>6 L</td><td>6 L</td><td>40 dollars</td></tr></table>
     <p class="big">The rules for success: arrive with at least 7 L, lose no more than half a liter, cost under 15 dollars.</p>`,qs:["Which design holds the most water at the start?","Which carrier meets all three rules? Explain from the table.","Which carrier would you not use, and which rule does it fail?"],key:["the open bucket, 10 L (3-5-ETS1-2)","The jug with a screw lid. It arrives with all 8 L, loses nothing, and costs 9 dollars. Another choice counts only if the student argues it against all three rules using the table. (3-5-ETS1-2)","Any reasoned rejection with the rule named: the open bucket fails the loss rule, 3 L spilled, and the backpack bladder fails the amount rule at 6 L and the cost rule at 40 dollars. Naming the rule is the part being rated. (3-5-ETS1-2)"]},{title:"Make the Test Fair",std:["3-5-ETS1-3"],n:3,dur:90,dir:"Answer out loud.",desc:"judging whether a test is fair, naming controlled variables, and identifying a failure point",html:()=>`<p class="big">Two sunshade fabrics were tested over the picnic table to see which one keeps the air under it cooler.</p>
     <table class="bigTable"><tr><th>Fabric</th><th>Time of day</th><th>Height above the table</th></tr>
     <tr><td>tight woven canvas</td><td>nine in the morning</td><td>2 m</td></tr>
     <tr><td>loose mesh net</td><td>two in the afternoon</td><td>3 m</td></tr></table>`,qs:["Is this test fair? Explain what you notice about it.","What two things would you make identical in a fair version of this test?","The loose mesh net tore at every corner where the rope was tied, on both test days. Name that weak spot, and say what you would change."],key:["No. Two things were different at once, the time of day and the height, so a cooler reading cannot be pinned on the fabric. The afternoon is hotter whatever the fabric. (3-5-ETS1-3)","Any two controlled variables: the same time of day, the same height, the same table, the same weather, the same thermometer in the same spot. (3-5-ETS1-3)","The failure point is the corners tearing at the tie points. Any improvement aimed there: sew a reinforced patch at each corner, add a metal eyelet, tie to a loop of webbing instead of the fabric, spread the pull across a longer edge. An improvement somewhere else does not count. (3-5-ETS1-3)"]}]},{id:25,title:"Maps and Places",short:"Maps",parts:[{std:["HSS-3.1"],n:4,dur:90,dir:"Use the map grid and the table. Answer out loud.",desc:"using a map grid and a table to describe physical and human features and where they sit",html:()=>`<p class="big">A map grid of the camp and the lake. North is the top row.</p>
     <table class="bigTable"><tr><th></th><th>west</th><th>middle</th><th>east</th></tr>
     <tr><th>north</th><td>${F.icon("pine",54)}<br>pine woods</td><td>${F.icon("mountain",54)}<br>lookout hill</td><td>${F.icon("drop",54)}<br>inlet creek</td></tr>
     <tr><th>middle</th><td>${F.icon("tent",54)}<br>tent field</td><td>${F.icon("cabin",54)}<br>dining hall</td><td>${F.icon("sprout",54)}<br>camp garden</td></tr>
     <tr><th>south</th><td>${F.icon("wave",54)}<br>lake</td><td>${F.icon("anchor",54)}<br>dock</td><td>${F.icon("bus",54)}<br>camp road</td></tr></table>
     <table class="bigTable"><tr><th>Place</th><th>Minutes to walk from the dining hall</th></tr>
     <tr><td>dock</td><td>2</td></tr><tr><td>tent field</td><td>4</td></tr>
     <tr><td>camp garden</td><td>5</td></tr><tr><td>lookout hill</td><td>14</td></tr></table>`,qs:["What lies directly south of the dining hall?","Which two directions do you walk to get from the dining hall to the inlet creek?","Name a natural feature here and a place people built.","Which place in the table is the longest walk? About how many times longer is that walk than the walk to the dock?"],key:["the dock (HSS-3.1)","north and east, in either order. The inlet creek sits in the north row and the east column. Partial: one of the two directions is approaching. (HSS-3.1)","Physical: the pine woods, the lookout hill, the creek, the lake. Human-made: the tent field, the dining hall, the garden, the dock, the camp road. One of each is what is being checked. Partial: one of the two kinds named is approaching. (HSS-3.1)","the lookout hill, 14 minutes, which is seven times the two-minute walk to the dock. Partial: the longest walk named with no comparison to the dock is approaching. (HSS-3.1)"]}]},{id:26,title:"Long Ago in This Place",short:"Long Ago",parts:[{title:"The First Nations Here",std:["HSS-3.2"],n:3,dur:90,dir:"Answer out loud. Use what is on the screen and what you have learned.",desc:"describing how water shaped where the American Indian nations of California lived, how settlers changed that, and how a nation is part of the state today",html:()=>`<p class="big">Lakes, rivers and marshes gave California nations fish, waterfowl, reeds and roots. Summer camps were often set up near water for exactly that reason. Many nations work today on protecting the same waters.</p>
      <p class="big">When settlers arrived in the 1800s they wanted the same water. Some traded with the nations already living there. Some worked alongside them. But settlers also fenced the meadows. They took the best land along the rivers. They let cattle into the places where nations had always gathered food. The nations lost much of their homeland. They stayed and kept their nations going anyway.</p>
     <div class="figure">${F.icon("wave",88)}${F.icon("duck",80)}</div>`,qs:["The screen names four things the lakes, rivers and marshes gave California nations. Name all four. Then say why summer camps were often set up near water.","Settlers came to land where nations were already living. Name one way settlers and nations worked with each other. One way the settlers’ arrival made life harder for the nation already there.","Are these nations only part of history? Name one way a nation is part of California now."],key:["Fish, waterfowl, reeds, and roots. Summer camps were set up near water because that is where those four things were. Partial: three of the four named, or all four with no reason given for the camps, is approaching. (HSS-3.2)","Working with each other: trading goods, settlers hiring nation members for work, learning from the nations where water and food were. Made life harder: meadows fenced off, the best river land taken, cattle eating the plants nations gathered, less land left to live on. One of each is what is being checked. Partial: one of the two kinds named is approaching. (HSS-3.2)","No. Any true present-day answer: nations have their own tribal governments, they work to protect rivers and lakes, there are language classes and cultural centers, people hold cultural events, members live and work across the state. Partial: saying no with no present-day example is approaching. (HSS-3.2)","Not scored, ask it anyway: which American Indian nation or nations have their homeland where this student lives? The answer is different for every family, so there is no key for it and it stays out of the rating. Tell the student the name if they do not know it, write it on the record sheet, and make it something to teach before the next check."]},{title:"A Town Over Time",std:["HSS-3.3"],n:3,dur:90,dir:"Look at the timeline. Answer out loud.",desc:"sequencing local historical events and describing the mark each period left on the land",html:()=>`<p class="big">A timeline for the town of Reed Landing, at the end of the lake.</p>
     <table class="bigTable"><tr><th>Year</th><th>What happened</th></tr>
     <tr><td>1859</td><td>a landing and a boat shed are built where the lake is deepest at the shore</td></tr>
     <tr><td>1884</td><td>a sawmill cuts the pines on the north shore and floats the logs across</td></tr>
     <tr><td>1921</td><td>a road reaches the landing and summer cabins go up along the east shore</td></tr>
     <tr><td>1963</td><td>the lake is raised by a low dam, and the old landing goes under water</td></tr>
     <tr><td>2004</td><td>the north shore, grown back in pines, becomes a county preserve</td></tr></table>`,qs:["Put these three in order, earliest first: the road, the low dam, the sawmill.","Which event changed the north shore. What did it do to it?","Pick one period on this timeline. What mark has it left? Think of the land or the water. Tell me one someone could still see today."],key:["sawmill, road, low dam. Partial: two of the three in the right order is approaching. (HSS-3.3)","the sawmill in 1884, which cut the pines off the north shore. Accept the 2004 preserve as a second answer, since the shore has grown back. Partial: naming the sawmill with no account of what it did to the shore is approaching. (HSS-3.3)","Any period with a physical mark named: the deep spot at the shore that set where the landing went, regrown pines on the north shore, the road, cabins along the east shore, the higher water line and the drowned old landing, the preserve boundary. Partial: naming a period with no mark on the land or the water named is approaching. (HSS-3.3)"]}]},{id:27,title:"Rules and Work",short:"Rules",parts:[{title:"Rules, Laws and Government",std:["HSS-3.4"],n:4,dur:105,dir:"Answer out loud.",desc:"telling rules from laws and naming the basic parts and levels of United States government",html:()=>`<p class="big">Camp has a rule. Nobody swims unless a counselor is on the dock. The county has a law about boats. Every boat must carry a life jacket for each person aboard.</p>
      <p class="big">The United States is made of parts. Each one keeps some power of their own. California and the other forty-nine states each make their own laws. Those laws are about schools, roads and lakes. American Indian nations are sovereign as well. That means a nation governs itself. It deals with the United States government as one government to another. All of them together make up the country.</p>
     <div class="figure">${F.icon("flag",88)}${F.icon("books",88)}</div>`,qs:["What is the difference between the camp rule and the county law?","Both are about water safety. Why does one of them need a government behind it?","The United States government has three parts. Name the part that makes laws and the part that decides what a law means.","Name two kinds of government inside the United States that each keep some power of their own. Then say what sovereign means."],key:["The camp rule is set by camp and applies at camp. The county law is made by a government, applies to everyone with a boat in the county, and the government decides what happens when it is broken. Partial: describing the camp rule with nothing said about who makes the county law is approaching. (HSS-3.4)","Because the law has to apply to everybody on the lake, including people camp has no say over, and only a government can make a rule that binds everyone and enforce it. Partial: saying a law is more important with no account of who it binds is approaching. (HSS-3.4)","the legislative branch, Congress or the state legislature, makes laws, and the judicial branch, the courts, decides what a law means. Partial: one of the two parts named is approaching. (HSS-3.4)","Any two of: the United States government, California or another state, an American Indian nation. Sovereign means that a government governs itself and deals with the United States government as one government to another, rather than being told what to do by it. Partial: two governments named with no account of what sovereign means is approaching. (HSS-3.4)"]},{title:"Choices and the Local Economy",std:["HSS-3.5"],n:4,dur:105,dir:"Look at the price list. Answer out loud.",desc:"basic economic reasoning about scarce money, trade-offs, goods and services",html:()=>`<p class="big">The camp store sells a few things and it also repairs canoes for a fee. A camper has 12 dollars for the whole week.</p>
     <table class="bigTable"><tr><th>Item</th><th>Price</th></tr>
     <tr><td>sun hat</td><td>8 dollars</td></tr><tr><td>water bottle</td><td>6 dollars</td></tr>
     <tr><td>postcard and stamp</td><td>2 dollars</td></tr></table>`,qs:["Can the camper buy all three with 12 dollars? Work it out.","She buys the hat and the postcard. What has she given up. What is the name for the thing you give up when you choose?","The store sells hats and it repairs canoes. Which is a good and which is a service?","Name a job in your town and say which of the two it is."],key:["No. 8 plus 6 plus 2 is 16 dollars, and she has 12. Partial: saying no with no total worked out is approaching. (HSS-3.5)","She gave up the water bottle. The idea is a trade-off, or opportunity cost: picking one thing means doing without another, because money is limited. The idea matters more than the term at this grade. Partial: naming what was given up with no idea of a trade-off, or the term with nothing given up named, is approaching. (HSS-3.5)","A hat is a good, something you can hold. Repairing a canoe is a service, work someone does for you. Partial: one of the two sorted right is approaching. (HSS-3.5)","Any real local job sorted correctly: a baker makes a good, a mechanic provides a service, a farmer produces a good, a lifeguard provides a service. Partial: a real job named with the good or service label wrong is approaching. (HSS-3.5)"]}]}];const WC=FLU.split(/\s+/).filter(Boolean).length;const readPart=STOPS[1].parts[0];readPart.n=WC;readPart.key[0]=readPart.key[0].replace("__WC__",WC);readPart.desc=`a ${WC}-word grade-level story read aloud`;const LEVELUPS={3:{id:"L3",lv:true,title:"Level Up: Read Between the Lines",std:["RL.4.1"],needs:["RL.3.1"],n:2,dir:"Answer out loud. Use details from the story.",html:()=>`<ol class="qlist"><li>The story never says that Theo was pleased at dinner. How do you know that he was? Give two details from the story.</li><li>Why do you think Delphine said nothing while the canoe was wandering? Use a detail from the story.</li></ol>${F.passage(STORY,STORY_TITLE,true)}`,key:["He was pleased, backed by two details: he sat up a little straighter, he had kept pulling all the way to the far dock and back, and Delphine told the whole table he had steered on his own. (RL.4.1, inference with details)","She knew the wandering was normal for a beginner and wanted him to keep trying, since she had already told him that everybody is terrible at this. Accept any answer tied to a detail from the story. (RL.4.1, inference with a detail)"]},4:{id:"L4",lv:true,title:"Level Up: Put It Together",std:["RI.4.1"],needs:["RI.3.1"],n:2,dir:"Answer out loud. Use details and examples from the texts.",html:()=>`<ol class="qlist"><li>Neither text says what happens to the lake if the shore plants are pulled out. Use details from both texts to explain it.</li><li>Why does camp wash dishes thirty steps back from the shore instead of three steps back? Use the texts to explain.</li></ol>${twoTexts()}`,key:["Bare soil would wash downhill into the lake. Text 2 says the roots of the shore plants hold the soil in place when it rains, and Text 1 says every drop that falls on the land runs downhill to the lake, so without roots the rain would carry the loose soil in with it. Neither text states this, so the student has to put the two details together. (RI.4.1, inference backed by details)","Thirty steps gives the soapy water enough ground to soak into, so it does not run on into the lake. Text 2 says that is the point of the rule, and Text 1 explains that water on the land runs downhill to the lake, so a few steps would not be far enough. (RI.4.1, inference with details)"]},8:{id:"L8",lv:true,title:"Level Up: Grown-Up Grammar",std:["L.4.1"],needs:["L.3.1"],n:3,dir:"Say each answer out loud.",html:()=>`<ol class="qlist"><li>Which sentence is right? A: We should of pulled the canoes up last night. B: We should have pulled the canoes up last night.</li><li>Put these words in the order that sounds right in English: <b>three / green / canvas / tarps</b></li><li>Change this sentence so it tells about what is happening right now: Delphine paddles in the stern.</li></ol>`,key:["B. “Should of” is not a correct form, so the modal auxiliary needs have. (L.4.1, modal auxiliaries and common usage errors)","three green canvas tarps. Number, then color, then what it is made of, then the noun. (L.4.1, ordering adjectives within a sentence)","Delphine is paddling in the stern. (L.4.1, present progressive verb tense)"]},12:{id:"L12",lv:true,title:"Level Up: Around and Across",std:["4.MD.A.3"],needs:["3.MD.C.7"],n:3,dir:"Solve on your paper and hold it up.",html:()=>`<ol class="qlist"><li>A tent pad is 9 meters long and 4 meters wide. What is its area? What is its perimeter?</li><li>A dock deck has an area of 56 square feet. One side is 7 feet long. How long is the other side, and what is the perimeter?</li><li>A rope fence runs all the way around a rectangle that is 24 meters by 15 meters. The rope comes in 6 meter pieces. How many pieces are needed?</li></ol>`,key:["Area 36 square meters, from 9 × 4. Perimeter 26 meters, from 9 + 4 + 9 + 4, or 2 × 13. (4.MD.A.3)","The other side is 8 feet, because 7 × 8 = 56. Perimeter 30 feet, from 2 × (7 + 8). (4.MD.A.3, area formula with an unknown factor)","13 pieces. The perimeter is 2 × (24 + 15) = 78 meters, and 78 ÷ 6 = 13. (4.MD.A.3)"]},14:{id:"L14",lv:true,title:"Level Up: Unlike Pieces",std:["4.NF.A.2"],needs:["3.NF.A.3"],n:3,dir:"Answer out loud and tell how you know. You can write on your paper.",html:()=>`<ol class="qlist"><li>Which is greater, 2/3 of a jug or 3/5 of the same jug?</li><li>Write &gt;, &lt;, or = to make it true: 5/8 ____ 1/2</li><li>Is 4/9 of a jug more or less than half a jug? Use half as your benchmark.</li></ol>`,key:["2/3. In fifteenths, 2/3 is 10/15 and 3/5 is 9/15, so 2/3 is greater. (4.NF.A.2, comparing fractions with different numerators and denominators)","5/8 &gt; 1/2. In eighths, 1/2 is 4/8, and 5/8 is more than 4/8. (4.NF.A.2)","Less than half. Half of 9 is 4 1/2, so 4/9 falls just under half. Accept the comparison in eighteenths: 4/9 is 8/18 and 1/2 is 9/18. (4.NF.A.2, comparing to a benchmark)"]}};const PASSAGE_STD=["RL.3.1","RL.3.4","RI.3.1","RI.3.9","W.3.8","W.3.2","RL.4.1","RI.4.1"];const MULT_N=10;const FRAC_DENS=[1,2,3,4,5,6,8];let multSel=[0,0],fracOn={};function multHtml(){let h=`<div class="tool-scroll"><table class="mult"><tr><th>×</th>`;for(let c=1;c<=MULT_N;c++)h+=`<th data-r="0" data-c="${c}" class="${multSel[1]===c?"hl":""}">${c}</th>`;h+="</tr>";for(let r=1;r<=MULT_N;r++){h+=`<tr><th data-r="${r}" data-c="0" class="${multSel[0]===r?"hl":""}">${r}</th>`;for(let c=1;c<=MULT_N;c++){const hr=multSel[0]===r,hc=multSel[1]===c;h+=`<td data-r="${r}" data-c="${c}" class="${hr&&hc?"pick":hr||hc?"hl":""}">${r*c}</td>`}h+="</tr>"}return h+`</table></div><p class="small">Click a number to light up its row and column. Click it again to clear.</p>`}function fracHtml(){return FRAC_DENS.map(d=>{const on=fracOn[d]||0;let r=`<div class="fs-row">`;for(let k=0;k<d;k++)r+=`<button class="fs-part${k<on?" on":""}" data-d="${d}" data-k="${k}">${d===1?"1 whole":"1/"+d}</button>`;return r+"</div>"}).join("")+`<p class="small">Click a piece to shade up to it. Click the last shaded piece to clear the row.</p>`}function lineHtml(){const rows=[[2,"halves"],[3,"thirds"],[4,"fourths"],[5,"fifths"],[6,"sixths"],[8,"eighths"]];return`<div style="display:flex;flex-direction:column;gap:6px">`+rows.map(r=>`<div style="text-align:center"><p class="fig-label" style="margin:0">0 to 1 in ${r[1]}</p>${F.numberLine({min:0,max:1,step:1/r[0],hideNumbers:true,ticks:[[0,"0"],[1,"1"]],width:520})}</div>`).join("")+`</div><p class="small">Count the equal spaces, not the tick marks. The 0 tick is where you start counting from.</p>`}function roundHtml(){return F.numberLine({min:420,max:450,step:5,labelEvery:10,marks:[435],width:560})+F.table(["Rounding to","What to look at"],[["The nearest 10","the ones digit"],["The nearest 100","the tens digit"]])+`<p class="small">Find the two round numbers the number sits between, then ask which one it is closer to. A number exactly halfway rounds up.</p>`}function areaHtml(){return F.table(["What to find","How"],[["Area of a rectangle","length × width, answer in square units"],["Area of an L shape","cut it into rectangles, find each area, then add them"],["A missing side","area ÷ the side you know"],["Perimeter","add all four sides, or 2 × (length + width)"]])+`<p class="small">Area counts the squares inside. Perimeter measures the trip around the outside.</p>`}function rulerHtml(){return F.row([F.ruler({length:2,px:150,parts:4}),"One inch is cut into 4 equal parts"])+F.table(["Mark","What to call it"],[["The long mark","a whole inch"],["The middle mark","a half, like 2 1/2"],["The two short marks","a fourth, like 2 1/4 or 2 3/4"]])+`<p class="small">Line the left end of the object up with the 0, then read the mark the right end lands on.</p>`}const SENT_SET={opinion:"opinion",facts:"facts",story:"story","W.3.1":"opinion","W.3.2":"facts","W.3.3":"story","W.3.8":"W.3.8","SL.3.2":"SL.3.2","SL.3.4":"SL.3.4","RI.3.9":"RI.3.9"};function sentSet(st){const ps=st&&st.parts&&st.parts.length?st.parts:st?[st]:[];for(const p of ps){const a=p.alt&&p.alt.key||p.wk||p.wt;if(a&&SENT_SET[a])return SENT_SET[a];const hit=(p.std||[]).find(c=>SENT_SET[c]);if(hit)return SENT_SET[hit]}return"opinion"}function starters(st){const k=sentSet(st);if(k==="story")return["Early one morning, ____.","First, ____.","Next, ____.","“____,” said ____.","Finally, ____."];if(k==="facts")return["A watershed is ____.","One fact is ____.","Also, ____.","Another fact is ____.","Now you know ____."];if(k==="W.3.8")return["The text says ____.","Water: ____.","Camp: ____."];if(k==="SL.3.2")return["The big idea is ____.","One detail is ____.","Another detail is ____.","The graph shows ____."];if(k==="SL.3.4")return["The place I know well is ____.","One fact about it is ____.","You can also ____.","The best part is ____."];if(k==="RI.3.9")return["Both texts say ____.","Text 1 says ____.","Text 2 says ____.","What is different is ____."];return["Camp should pick ____ because ____.","One reason is ____.","For example, ____.","That is why ____."]}function sentHtml(st){return`<ul class="starters">${starters(st).map(x=>`<li>${x}</li>`).join("")}</ul>`}const TOOLS={mult:{name:"Multiplication chart",std:["3.OA.A.1","3.OA.A.2","3.OA.D.8","3.MD.C.7","4.MD.A.3"],html:multHtml,bind:(b,r)=>b.querySelectorAll("[data-r]").forEach(c=>c.onclick=()=>{const row=+c.dataset.r,k=+c.dataset.c;multSel=multSel[0]===row&&multSel[1]===k?[0,0]:[row,k];r()})},nline:{name:"Fraction number lines",std:["3.NF.A.2","3.NF.A.3","4.NF.A.2"],html:lineHtml},frac:{name:"Fraction strips",std:["3.NF.A.1","3.NF.A.3","3.G.A.2","4.NF.A.2"],html:fracHtml},round:{name:"Rounding number line",std:["3.NBT.A.1"],html:roundHtml},area:{name:"Area and perimeter card",std:["3.MD.C.7","3.G.A.2","4.MD.A.3"],html:areaHtml},ruler:{name:"Inch ruler card",std:["3.MD.B.4"],html:rulerHtml},sent:{name:"Sentence starters",std:["W.3.1","W.3.2","W.3.3","W.3.8","SL.3.2","SL.3.4","RI.3.9"],html:sentHtml}};const SUP_CAVEATS=[{t:"mult",std:["3.OA.A.1","3.OA.A.2"],msg:"The multiplication chart gives the facts, so rate on whether the student can explain the equal groups or the equal shares, not on the fact itself."},{t:"mult",std:["3.OA.D.8","3.MD.C.7","4.MD.A.3"],msg:"The multiplication chart gives the products. Rate on the setup, the estimate, and the unit, not on the arithmetic."},{t:"nline",std:["3.NF.A.2"],msg:"The number line tool already shows the equal spaces from 0 to 1, so the partitioning is done for the student. Rate on whether the student can name the point as a fraction and count the spaces from 0."},{t:"nline",std:["3.NF.A.3","4.NF.A.2"],msg:"Lined-up number lines let the student see which fraction is farther from 0, so count the comparisons as supported, not independent."},{t:"frac",std:["3.NF.A.1"],msg:"The strips show equal parts already made, so rate on whether the student can name the shaded amount and the unit fraction rather than on spotting equal parts."},{t:"frac",std:["3.NF.A.3"],msg:"Fraction strips show the piece sizes and the equal shading, so rate on whether the student can explain what the strips show rather than on the comparison itself."},{t:"frac",std:["3.G.A.2"],msg:"The strips show equal parts already cut, so rate on whether the student names one part as a unit fraction of the whole."},{t:"round",std:["3.NBT.A.1"],msg:"The rounding card names the digit to look at and the number line shows where 435 sits, so count these answers as supported, not independent."},{t:"area",std:["3.MD.C.7","3.G.A.2","4.MD.A.3"],msg:"The card gives the method for area, perimeter, a missing side, and cutting an L shape apart. Count those items as supported, not independent."},{t:"ruler",std:["3.MD.B.4"],msg:"The ruler card names the half and fourth marks for the student, so rate on whether the student lines the object up at 0 and reads the right mark."},{t:"sent",std:["W.3.1","W.3.2","W.3.3"],msg:"Sentence starters supply the opening, the linking words, and the closing, so count those checks as supported, not independent."},{t:"sent",std:["W.3.8"],msg:"Sentence starters give the student the note categories, so rate on the facts chosen and on how brief the notes are."},{t:"sent",std:["SL.3.2","SL.3.4","RI.3.9"],msg:"The frames name main idea, detail, and difference for the student, so rate on whether the content of each answer is right."},{t:"passage",std:["RL.3.1","RL.3.4","RI.3.1","RI.3.9","W.3.8","W.3.2","RL.4.1","RI.4.1"],msg:"If the passage was read to the student, this stop shows listening comprehension, not reading."}];return{stops:STOPS,levelups:LEVELUPS,tools:TOOLS,supCaveats:SUP_CAVEATS,passageStd:PASSAGE_STD}}});
